const MACRO_NAME = "Strip the Husk";
const DAMAGE_TYPE = "rending";

const getSpeakerActor = () => {
  const speaker = ChatMessage.getSpeaker();
  if (speaker.token) {
    const token = canvas.tokens?.get(speaker.token);
    if (token?.actor) return token.actor;
  }
  if (speaker.actor) return game.actors?.get(speaker.actor);
  return null;
};

const getSpeakerToken = () => {
  if (canvas.tokens?.controlled?.length) return canvas.tokens.controlled[0];
  const speaker = ChatMessage.getSpeaker();
  if (speaker.token) return canvas.tokens?.get(speaker.token) ?? null;
  return null;
};

const clampTarget = (base, modifier) => {
  const capped = Math.max(-60, Math.min(60, modifier));
  return base + capped;
};

const computeDegrees = (target, rollTotal) => {
  const success = rollTotal <= target;
  if (success) {
    const degree = Math.floor(target / 10) - Math.floor(rollTotal / 10);
    return { success: true, dos: Math.max(1 + degree, 1), dof: 0 };
  }
  const degree = Math.floor(rollTotal / 10) - Math.floor(target / 10);
  return { success: false, dos: 0, dof: Math.max(1 + degree, 1) };
};

const degreeScore = degrees => (degrees.success ? degrees.dos : -degrees.dof);

const getTokenCenter = token => {
  if (token?.center) return token.center;
  if (typeof token?.getCenter === "function") return token.getCenter();
  return null;
};

const isWallBlocking = (origin, target) => {
  const walls = canvas.walls;
  if (!walls || !origin || !target) return false;
  const ray = new Ray(origin, target);
  return walls.checkCollision(ray, { type: "sight", mode: "any" });
};

const getVisibleHitLocations = (originToken, targetToken) => {
  const origin = getTokenCenter(originToken);
  if (!origin) return ["ARMOUR.BODY"];
  const bounds = targetToken.bounds;
  if (!bounds) return ["ARMOUR.BODY"];

  const points = [
    { key: "ARMOUR.HEAD", x: bounds.x + bounds.width / 2, y: bounds.y + bounds.height * 0.15 },
    { key: "ARMOUR.BODY", x: bounds.x + bounds.width / 2, y: bounds.y + bounds.height * 0.5 },
    { key: "ARMOUR.LEFT_ARM", x: bounds.x + bounds.width * 0.2, y: bounds.y + bounds.height * 0.45 },
    { key: "ARMOUR.RIGHT_ARM", x: bounds.x + bounds.width * 0.8, y: bounds.y + bounds.height * 0.45 },
    { key: "ARMOUR.LEFT_LEG", x: bounds.x + bounds.width * 0.35, y: bounds.y + bounds.height * 0.85 },
    { key: "ARMOUR.RIGHT_LEG", x: bounds.x + bounds.width * 0.65, y: bounds.y + bounds.height * 0.85 }
  ];

  const visible = points.filter(point => !isWallBlocking(origin, point));
  return visible.length ? visible.map(point => point.key) : ["ARMOUR.BODY"];
};

const applyDamageNoArmor = async (actor, amount) => {
  const toughness = actor.characteristics?.toughness?.bonus ?? 0;
  const applied = Math.max(amount - toughness, 0);
  const wounds = actor.system.wounds.value;
  const maxWounds = actor.system.wounds.max;
  let critical = actor.system.wounds.critical;
  let newWounds = wounds + applied;
  let newCritical = critical;
  if (newWounds > maxWounds) {
    newCritical += (newWounds - maxWounds);
    newWounds = maxWounds;
  }
  await actor.update({
    "system.wounds.value": newWounds,
    "system.wounds.critical": newCritical
  });
  return { applied, toughness };
};

const applyStatusEffect = async (actor, statusId) => {
  await actor.toggleStatusEffect(statusId, { active: true });
};

const buildDialog = (actor, targetToken, visibleLocations, blocked) => new Promise(resolve => {
  const targetName = targetToken ? targetToken.name : "press t to target";
  const locationChecks = [
    "ARMOUR.HEAD",
    "ARMOUR.BODY",
    "ARMOUR.LEFT_ARM",
    "ARMOUR.RIGHT_ARM",
    "ARMOUR.LEFT_LEG",
    "ARMOUR.RIGHT_LEG"
  ].map(loc => {
    const localized = game.i18n?.localize?.(loc) ?? loc;
    const checked = visibleLocations.includes(loc) ? "checked" : "";
    return `<label><input type="checkbox" name="loc" value="${loc}" ${checked} /> ${localized}</label>`;
  }).join("<br>");

  const content = `
    <div class="strip-husk">
      <h2>${MACRO_NAME}</h2>
      <p>Target: <strong>${targetName}</strong></p>
      <p>Line of Effect: <strong>${blocked ? "Blocked" : "Clear"}</strong></p>
      <div class="form-group">
        <label>Navigator WP</label>
        <input type="text" value="${actor.characteristics?.willpower?.total ?? 0}" disabled />
      </div>
      <div class="form-group">
        <label>Navigator WP Modifier</label>
        <input type="number" name="navigatorModifier" value="0" />
      </div>
      <div class="form-group">
        <label>Target WP Modifier</label>
        <input type="number" name="targetModifier" value="0" />
      </div>
      <div class="form-group">
        <label>Level</label>
        <select name="level">
          <option value="novice">Novice</option>
          <option value="adept">Adept</option>
          <option value="master">Master</option>
        </select>
      </div>
      <div class="form-group">
        <label>Visible Hit Locations (uncheck if blocked)</label>
        <div>${locationChecks}</div>
      </div>
    </div>`;
  new Dialog({
    title: MACRO_NAME,
    content,
    buttons: {
      cast: {
        icon: "<i class=\"fa-solid fa-bolt\"></i>",
        label: "Cast",
        callback: html => {
          const locations = Array.from(html.find("input[name=loc]:checked")).map(el => el.value);
          resolve({
            navigatorModifier: Number(html.find("[name=navigatorModifier]").val() ?? 0),
            targetModifier: Number(html.find("[name=targetModifier]").val() ?? 0),
            level: html.find("[name=level]").val(),
            locations
          });
        }
      },
      cancel: {
        icon: "<i class=\"fa-solid fa-times\"></i>",
        label: "Cancel",
        callback: () => resolve(null)
      }
    },
    default: "cast"
  }).render(true);
});

const actor = getSpeakerActor();
const originToken = getSpeakerToken();
if (!actor || !originToken) {
  ui.notifications.warn(`${MACRO_NAME}: Select a token first.`);
  return;
}

const targetToken = Array.from(game.user?.targets ?? [])[0] ?? null;
const blocked = targetToken ? isWallBlocking(getTokenCenter(originToken), getTokenCenter(targetToken)) : false;
const visibleLocations = targetToken ? getVisibleHitLocations(originToken, targetToken) : ["ARMOUR.BODY"];
const dialog = await buildDialog(actor, targetToken, visibleLocations, blocked);
if (!dialog) return;

if (!targetToken?.actor) {
  ui.notifications.warn(`${MACRO_NAME}: No target selected (press T to target).`);
  return;
}

const navigatorWp = actor.characteristics?.willpower?.total ?? 0;
const targetWp = targetToken.actor.characteristics?.willpower?.total ?? 0;

const navigatorTarget = clampTarget(navigatorWp, dialog.navigatorModifier);
const targetTarget = clampTarget(targetWp, dialog.targetModifier);

const navigatorRoll = await new Roll("1d100").evaluate({ async: true });
const targetRoll = await new Roll("1d100").evaluate({ async: true });

await navigatorRoll.toMessage({
  speaker: ChatMessage.getSpeaker({ actor, token: originToken.document }),
  flavor: `${MACRO_NAME}: ${actor.name} Willpower vs ${navigatorTarget} (${dialog.navigatorModifier >= 0 ? "+" : ""}${dialog.navigatorModifier})`
});

await targetRoll.toMessage({
  speaker: ChatMessage.getSpeaker({ actor: targetToken.actor, token: targetToken.document }),
  flavor: `${MACRO_NAME}: ${targetToken.name} Willpower vs ${targetTarget} (${dialog.targetModifier >= 0 ? "+" : ""}${dialog.targetModifier})`
});

const navigatorDegrees = computeDegrees(navigatorTarget, navigatorRoll.total);
const targetDegrees = computeDegrees(targetTarget, targetRoll.total);
const net = degreeScore(navigatorDegrees) - degreeScore(targetDegrees);

const summaryLines = [
  `<strong>${MACRO_NAME}</strong>`,
  `Level: ${dialog.level.toUpperCase()}`,
  `${actor.name}: ${navigatorRoll.total} vs ${navigatorTarget} → ${navigatorDegrees.success ? "Success" : "Failure"} (${navigatorDegrees.dos} DoS${navigatorDegrees.dof ? `, ${navigatorDegrees.dof} DoF` : ""})`,
  `${targetToken.name}: ${targetRoll.total} vs ${targetTarget} → ${targetDegrees.success ? "Success" : "Failure"} (${targetDegrees.dos} DoS${targetDegrees.dof ? `, ${targetDegrees.dof} DoF` : ""})`,
  `Difference: ${net}`,
  `Line of Effect: ${blocked ? "Blocked" : "Clear"}`
];

if (net <= 0) {
  summaryLines.push(`${targetToken.name} resists Strip the Husk.`);
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor, token: originToken.document }),
    content: `<div class="dh-roll">${summaryLines.map(line => `<p>${line}</p>`).join("")}</div>`
  });
  return;
}

const action = await new Promise(resolve => {
  const content = `
    <p>${targetToken.name} is affected. Difference: ${net}.</p>
    <div class="form-group">
      <label>Deny WP Modifier</label>
      <input type="number" name="denyModifier" value="0" />
    </div>`;
  new Dialog({
    title: `${MACRO_NAME}: ${targetToken.name}`,
    content,
    buttons: {
      apply: {
        icon: "<i class=\"fa-solid fa-bolt\"></i>",
        label: "Apply",
        callback: html => resolve({ type: "apply", denyModifier: Number(html.find("[name=denyModifier]").val() ?? 0) })
      },
      deny: {
        icon: "<i class=\"fa-solid fa-ban\"></i>",
        label: "Deny",
        callback: html => resolve({ type: "deny", denyModifier: Number(html.find("[name=denyModifier]").val() ?? 0) })
      },
      modify: {
        icon: "<i class=\"fa-solid fa-wand-magic\"></i>",
        label: "Modify",
        callback: html => resolve({ type: "modify", denyModifier: Number(html.find("[name=denyModifier]").val() ?? 0) })
      }
    },
    default: "apply"
  }).render(true);
});

let finalNet = net;
if (action.type === "deny") {
  const denyTarget = clampTarget(targetWp, action.denyModifier);
  const denyRoll = await new Roll("1d100").evaluate({ async: true });
  await denyRoll.toMessage({
    speaker: ChatMessage.getSpeaker({ actor: targetToken.actor, token: targetToken.document }),
    flavor: `${MACRO_NAME}: ${targetToken.name} Deny vs ${denyTarget} (${action.denyModifier >= 0 ? "+" : ""}${action.denyModifier})`
  });
  const denyDegrees = computeDegrees(denyTarget, denyRoll.total);
  if (denyDegrees.success) {
    summaryLines.push(`${targetToken.name} denied the power.`);
    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor, token: originToken.document }),
      content: `<div class="dh-roll">${summaryLines.map(line => `<p>${line}</p>`).join("")}</div>`
    });
    return;
  }
}

if (action.type === "modify") {
  const adjust = await new Promise(resolve => {
    new Dialog({
      title: `${MACRO_NAME}: Modify Difference`,
      content: `<div class="form-group"><label>Adjust Difference</label><input type="number" name="adjust" value="0" /></div>`,
      buttons: {
        apply: {
          icon: "<i class=\"fa-solid fa-check\"></i>",
          label: "Apply",
          callback: html => resolve(Number(html.find("[name=adjust]").val() ?? 0))
        }
      },
      default: "apply"
    }).render(true);
  });
  finalNet = net + adjust;
}

if (finalNet <= 0) {
  summaryLines.push(`${targetToken.name} resists after modifiers.`);
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ actor, token: originToken.document }),
    content: `<div class="dh-roll">${summaryLines.map(line => `<p>${line}</p>`).join("")}</div>`
  });
  return;
}

let damageFormula = "1d10";
let prone = false;
let requiresPin = false;

if (dialog.level === "novice") {
  damageFormula = "1d10";
  prone = true;
}
if (dialog.level === "adept") {
  damageFormula = `1d10 + ${finalNet}`;
  prone = true;
}
if (dialog.level === "master") {
  damageFormula = `2d10 + ${finalNet}`;
  prone = true;
  requiresPin = true;
}

const locationPool = dialog.locations.length ? dialog.locations : ["ARMOUR.BODY"];
const locationKey = locationPool[Math.floor(Math.random() * locationPool.length)];
const locationLabel = game.i18n?.localize?.(locationKey) ?? locationKey;

const damageRoll = await new Roll(damageFormula).evaluate({ async: true });
await damageRoll.toMessage({
  speaker: ChatMessage.getSpeaker({ actor, token: originToken.document }),
  flavor: `${MACRO_NAME}: Damage (${damageFormula}) to ${targetToken.name} [${locationLabel}]`
});

const damageResult = await applyDamageNoArmor(targetToken.actor, damageRoll.total);
summaryLines.push(`${targetToken.name} takes ${damageResult.applied} ${DAMAGE_TYPE} damage (TB ${damageResult.toughness} applied, no armour). Hit: ${locationLabel}.`);

if (prone) {
  await applyStatusEffect(targetToken.actor, "prone");
  summaryLines.push(`${targetToken.name} is now Prone.`);
}

if (requiresPin) {
  const pinTarget = targetWp;
  const pinRoll = await new Roll("1d100").evaluate({ async: true });
  await pinRoll.toMessage({
    speaker: ChatMessage.getSpeaker({ actor: targetToken.actor, token: targetToken.document }),
    flavor: `${MACRO_NAME}: ${targetToken.name} Pinning Willpower vs ${pinTarget}`
  });
  const pinDegrees = computeDegrees(pinTarget, pinRoll.total);
  if (!pinDegrees.success) {
    await applyStatusEffect(targetToken.actor, "pinned");
    summaryLines.push(`${targetToken.name} is now Pinned.`);
  }
}

await ChatMessage.create({
  speaker: ChatMessage.getSpeaker({ actor, token: originToken.document }),
  content: `<div class="dh-roll">${summaryLines.map(line => `<p>${line}</p>`).join("")}</div>`
});
